import { NextRequest, NextResponse } from "next/server";
import { supabaseAdmin } from "@/lib/supabase/server";
import { updateProductSchema } from "@atelier/shared";

// GET /api/products/:id - Get product by ID
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    if (!supabaseAdmin) {
      return NextResponse.json(
        { error: "Database not configured" },
        { status: 500 }
      );
    }

    const { id } = await params;

    const { data, error } = await supabaseAdmin
      .from("products")
      .select("*")
      .eq("id", id)
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Product not found" },
          { status: 404 }
        );
      }
      console.error("Error fetching product:", error);
      return NextResponse.json(
        { error: "Failed to fetch product" },
        { status: 500 }
      );
    }

    const product = {
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      brand: data.brand,
      category: data.category,
      sku: data.sku,
      handle: data.handle,
      url: data.url,
      sizeTypeId: data.size_type_id,
      thumbnailUrl: data.thumbnail_url,
      previewImageUrl: data.preview_image_url,
      createdAt: data.created_at,
      updatedAt: data.updated_at,
    };

    return NextResponse.json(product);
  } catch (error) {
    console.error("Error in GET /api/products/:id:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

// PATCH /api/products/:id - Update product
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    if (!supabaseAdmin) {
      return NextResponse.json(
        { error: "Database not configured" },
        { status: 500 }
      );
    }

    const { id } = await params;
    const body = await request.json();
    const validated = updateProductSchema.parse(body);

    const updateData: Record<string, unknown> = {};
    if (validated.shopId !== undefined) updateData.shop_id = validated.shopId;
    if (validated.name !== undefined) updateData.name = validated.name;
    if (validated.brand !== undefined) updateData.brand = validated.brand;
    if (validated.category !== undefined) updateData.category = validated.category;
    if (validated.sku !== undefined) updateData.sku = validated.sku;
    if (validated.handle !== undefined) updateData.handle = validated.handle;
    if (validated.url !== undefined) updateData.url = validated.url;
    if (validated.sizeTypeId !== undefined) updateData.size_type_id = validated.sizeTypeId;
    if (validated.thumbnailUrl !== undefined) updateData.thumbnail_url = validated.thumbnailUrl;
    if (validated.previewImageUrl !== undefined) updateData.preview_image_url = validated.previewImageUrl;

    updateData.updated_at = new Date().toISOString();

    const { data, error } = await supabaseAdmin
      .from("products")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Product not found" },
          { status: 404 }
        );
      }
      console.error("Error updating product:", error);
      return NextResponse.json(
        { error: "Failed to update product" },
        { status: 500 }
      );
    }

    const product = {
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      brand: data.brand,
      category: data.category,
      sku: data.sku,
      handle: data.handle,
      url: data.url,
      sizeTypeId: data.size_type_id,
      thumbnailUrl: data.thumbnail_url,
      previewImageUrl: data.preview_image_url,
      createdAt: data.created_at,
      updatedAt: data.updated_at,
    };

    return NextResponse.json(product);
  } catch (error) {
    if (error instanceof Error && error.name === "ZodError") {
      return NextResponse.json(
        { error: "Invalid request body", details: error },
        { status: 400 }
      );
    }

    console.error("Error in PATCH /api/products/:id:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

// DELETE /api/products/:id - Delete product
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    if (!supabaseAdmin) {
      return NextResponse.json(
        { error: "Database not configured" },
        { status: 500 }
      );
    }

    const { id } = await params;

    const { error } = await supabaseAdmin
      .from("products")
      .delete()
      .eq("id", id);

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Product not found" },
          { status: 404 }
        );
      }
      console.error("Error deleting product:", error);
      return NextResponse.json(
        {
          error: "Failed to delete product",
          message: error.message,
          details: error.code,
        },
        { status: 500 }
      );
    }

    return NextResponse.json({ success: true }, { status: 200 });
  } catch (error) {
    console.error("Error in DELETE /api/products/:id:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
